import mongoose from "mongoose";

const MediaSchema = new mongoose.Schema(
  {
    mediaID: {
      // md5 hash of the image generated by aws
      type: String,
      required: true,
      unique: true,
    },
    imageHash: String, // hash of the image without exif data
    deploymentId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Deployment",
    },
    timestamp: {
      type: Date,
      required: true,
    },
    publicURL: String,
    videoUrl: {
      type: String,
      default: null,
    },
    relativePath: [String],
    filePath: String,
    filePublic: Boolean,
    fileName: String,
    fileMediatype: String,
    fileLocations: [
      {
        publicURL: String,
        relativePath: [String],
        filePath: String,
        filePublic: Boolean,
        fileName: String,
        createdAt: { type: Date, default: Date.now },
        updatedAt: { type: Date, default: Date.now },
      },
    ],
    exifData: mongoose.Schema.Types.Mixed,
    aiResults: [
      {
        modelName: String,
        runDate: String, // Consider Date type if needed
        confBlank: Number,
        confHuman: Number,
        confAnimal: Number,
        animalDetections: [
          {
            bbox: [Number],
            conf: Number,
          },
        ],
      },
    ],
    favorite: {
      type: Boolean,
      default: false,
    },
    favoriteCount: {
      type: Number,
      default: 0,
    },
    favorites: [
      {
        type: mongoose.Schema.Types.ObjectId,
        ref: "User",
      },
    ],
    mediaComments: [
      {
        text: String,
        author: { type: mongoose.Schema.Types.ObjectId, ref: "User" },
        timestamp: { type: Date, default: Date.now },
      },
    ],
    reviewed: {
      type: Boolean,
      default: false,
    },
    accepted: {
      type: Boolean,
      default: false,
    },
    reviewCount: {
      type: Number,
      default: 0,
    },
    observations: [
      {
        type: mongoose.Schema.Types.ObjectId,
        ref: "Observation",
      },
    ],
    lastObservation: {
      type: Date,
      default: null,
    },
    consensusStatus: {
      type: String,
      enum: ["Pending", "ConsensusReached", "MoreAnnotationsNeeded"],
      default: "Pending",
    },
    speciesConsensus: [
      {
        observationType: String,
        scientificName: String,
        taxonID: String,
        count: Number,
        accepted: {
          type: Boolean,
          default: false,
        },
        observationCount: {
          type: Number,
          default: 0,
        },
      },
    ],
    reviewers: [
      {
        type: mongoose.Schema.Types.ObjectId,
        ref: "User",
      },
    ],
    needsReview: {
      type: Boolean,
      default: false,
    },
    flagged: {
      type: Boolean,
      default: false,
    },
    removed: {
      type: Boolean,
      default: false,
    },
    // Pre-generated random float used for O(log n) random document lookups.
    // Replaces slow $sample-after-$match aggregations. Indexed so queries
    // can seek directly to a random point in the B-tree.
    randomSeed: {
      type: Number,
      default: () => Math.random(),
      index: true,
    },
  },
  { timestamps: true },
);

// Add a pre-save hook to ensure timestamp is always valid
MediaSchema.pre("save", function (next) {
  if (this.timestamp && isNaN(this.timestamp.getTime())) {
    this.timestamp = new Date();
  }
  next();
});

// --- Indexes ---
// File path lookups
MediaSchema.index({ relativePath: 1 });
// Identify page: filter by AI confidence scores
MediaSchema.index({ flagged: 1, "aiResults.confAnimal": 1, "aiResults.confHuman": 1 });
// Navigation by timestamp (prev/next image)
MediaSchema.index({ flagged: 1, timestamp: 1 });
// Filtered by deployment + timestamp navigation
MediaSchema.index({ flagged: 1, deploymentId: 1, timestamp: 1 });
// Random favorite image lookup
MediaSchema.index({ favorite: 1 });
// Explore page: consensus-based browsing sorted by timestamp
MediaSchema.index({ flagged: 1, consensusStatus: 1, timestamp: -1 });
// Explore page: species consensus + review status queries
MediaSchema.index({ "speciesConsensus.scientificName": 1, timestamp: -1 });
// Review count queries (reviewed=true filter)
MediaSchema.index({ flagged: 1, reviewCount: 1, timestamp: -1 });
// Random image lookups via randomSeed (replaces slow $sample after $match)
MediaSchema.index({ flagged: 1, randomSeed: 1 });
MediaSchema.index({ flagged: 1, deploymentId: 1, randomSeed: 1 });
MediaSchema.index({ favorite: 1, randomSeed: 1 });

/**
 * Find a single random document matching the query using the randomSeed field.
 * Works by picking a random float and seeking to the nearest document in the
 * B-tree index — O(log n) instead of the O(n) full-scan that $sample requires
 * after a $match stage.
 *
 * Tries randomSeed >= rand first, then wraps around to < rand if nothing found
 * (handles edge cases where rand is near 1.0).
 */
MediaSchema.statics.findOneRandom = async function (query = {}, { lean = false } = {}) {
  const rand = Math.random();
  let q = this.findOne({ ...query, randomSeed: { $gte: rand } }).sort({ randomSeed: 1 });
  if (lean) q = q.lean();
  let doc = await q;
  if (!doc) {
    q = this.findOne({ ...query, randomSeed: { $lt: rand } }).sort({ randomSeed: -1 });
    if (lean) q = q.lean();
    doc = await q;
  }
  return doc;
};

/**
 * Find multiple random documents matching the query using the randomSeed field.
 * Picks a random starting point and grabs `limit` documents from there,
 * wrapping around if needed. Documents are spread uniformly across the
 * randomSeed space so results are well-distributed.
 */
MediaSchema.statics.findRandomSample = async function (query = {}, limit = 1) {
  const rand = Math.random();

  // Grab docs starting from a random point going forward
  let docs = await this.find({ ...query, randomSeed: { $gte: rand } })
    .sort({ randomSeed: 1 })
    .limit(limit)
    .lean();

  // If we didn't get enough (rand was near 1.0), wrap around from the start
  if (docs.length < limit) {
    const remaining = limit - docs.length;
    const moreDocs = await this.find({ ...query, randomSeed: { $lt: rand } })
      .sort({ randomSeed: 1 })
      .limit(remaining)
      .lean();
    docs = docs.concat(moreDocs);
  }

  return docs;
};

// Updated method to update observations and check for consensus
MediaSchema.methods.updateObservationsAndCheckConsensus = async function () {
  await this.populate("observations");
  this.lastObservation = new Date();

  const observationTypes = {};
  const uniqueReviewers = new Set();

  this.observations.forEach((obs) => {
    if (!observationTypes[obs.observationType]) {
      observationTypes[obs.observationType] = [];
    }
    observationTypes[obs.observationType].push(obs);

    // Add the creator of the observation to the set of unique reviewers
    uniqueReviewers.add(obs.creator.toString());
  });

  this.speciesConsensus = Object.entries(observationTypes).flatMap(
    ([observationType, observations]) => {
      const speciesCounts = {};
      observations.forEach((obs) => {
        if (obs.observationType === "animal") {
          const key = `${obs.scientificName}-${obs.count}`;
          speciesCounts[key] = (speciesCounts[key] || 0) + 1;
        } else {
          const key = `${observationType}-${obs.count || 1}`;
          speciesCounts[key] = (speciesCounts[key] || 0) + 1;
        }
      });

      return Object.entries(speciesCounts).map(([key, count]) => {
        const [identifier, observedCount] = key.split("-");
        if (observationType === "animal") {
          return {
            observationType,
            taxonID: identifier,
            scientificName: identifier,
            count: parseInt(observedCount) || 0,
            accepted: count >= 3,
            observationCount: count,
          };
        } else {
          return {
            observationType,
            taxonID: null,
            scientificName: null,
            count: parseInt(observedCount) || 1,
            accepted: count >= 3,
            observationCount: count,
          };
        }
      });
    },
  );

  // Update consensusStatus based on speciesConsensus
  const allAccepted = this.speciesConsensus.every(
    (consensus) => consensus.accepted,
  );
  const anyAccepted = this.speciesConsensus.some(
    (consensus) => consensus.accepted,
  );

  if (allAccepted) {
    this.consensusStatus = "ConsensusReached";
  } else if (anyAccepted) {
    this.consensusStatus = "MoreAnnotationsNeeded";
  } else {
    this.consensusStatus = "Pending";
  }

  // Update reviewCount and reviewers
  this.reviewers = Array.from(uniqueReviewers);
  this.reviewCount = this.reviewers.length;

  await this.save();
};

// New method to add an observation and update consensus
MediaSchema.methods.addObservationAndUpdateConsensus = async function (
  observation,
) {
  this.observations.push(observation);

  // Add the creator of the observation to the reviewers array if not already present
  if (!this.reviewers.includes(observation.creator)) {
    this.reviewers.push(observation.creator);
  }

  await this.updateObservationsAndCheckConsensus();
};

// Updated static method to add an observation and update consensus for a specific media
MediaSchema.statics.addObservationAndUpdateConsensusForMedia = async function (
  mediaId,
  observation,
) {
  const media = await this.findOne({ mediaID: mediaId });
  if (media) {
    await media.addObservationAndUpdateConsensus(observation);
  }
};

/**
 * Pure helper: derive the speciesConsensus array from a list of observations.
 * Same grouping rules as updateObservationsAndCheckConsensus above: agreement
 * is counted per (observationType, scientificName, count); 3+ agreeing
 * observations mark an entry as accepted.
 */
function buildSpeciesConsensus(observations) {
  const byType = new Map();
  for (const obs of observations) {
    const type = obs.observationType;
    if (!byType.has(type)) byType.set(type, new Map());
    const counts = byType.get(type);
    const identifier = type === "animal" ? obs.scientificName : null;
    const observedCount =
      type === "animal" ? obs.count : obs.count || 1;
    // Key on a tuple instead of a "name-count" string so hyphenated names
    // can't be split incorrectly.
    const key = JSON.stringify([identifier, observedCount]);
    const entry = counts.get(key) || { identifier, observedCount, n: 0 };
    entry.n += 1;
    counts.set(key, entry);
  }

  const result = [];
  for (const [observationType, counts] of byType) {
    for (const { identifier, observedCount, n } of counts.values()) {
      if (observationType === "animal") {
        result.push({
          observationType,
          taxonID: identifier,
          scientificName: identifier,
          count: parseInt(observedCount) || 0,
          accepted: n >= 3,
          observationCount: n,
        });
      } else {
        result.push({
          observationType,
          taxonID: null,
          scientificName: null,
          count: parseInt(observedCount) || 1,
          accepted: n >= 3,
          observationCount: n,
        });
      }
    }
  }
  return result;
}

/**
 * Recompute a media document's observation summary from scratch using every
 * Observation that references it. One findOne-free read + one updateOne, no
 * matter how many observations were just added — this replaces the old
 * per-observation load → populate → save loop on the save path, and is
 * idempotent (safe to re-run; never duplicates ids in `observations`).
 */
MediaSchema.statics.recomputeConsensusForMedia = async function (mediaId) {
  if (!mediaId) return false;
  const Observation = mongoose.model("Observation");
  const observations = await Observation.find(
    { mediaId },
    { observationType: 1, scientificName: 1, count: 1, creator: 1 },
  ).lean();

  const reviewers = [
    ...new Set(
      observations.filter((o) => o.creator).map((o) => o.creator.toString()),
    ),
  ];
  const speciesConsensus = buildSpeciesConsensus(observations);

  let consensusStatus = "Pending";
  if (speciesConsensus.length > 0) {
    if (speciesConsensus.every((c) => c.accepted)) {
      consensusStatus = "ConsensusReached";
    } else if (speciesConsensus.some((c) => c.accepted)) {
      consensusStatus = "MoreAnnotationsNeeded";
    }
  }

  const result = await this.updateOne(
    { mediaID: mediaId },
    {
      $set: {
        observations: observations.map((o) => o._id),
        reviewers,
        reviewCount: reviewers.length,
        speciesConsensus,
        consensusStatus,
        lastObservation: new Date(),
      },
    },
  );
  return result.matchedCount > 0;
};

// The Observation model's save/remove/update hooks call this name; it was never
// defined before, so those hooks would have thrown. Alias it to the recompute.
MediaSchema.statics.updateObservationsForMedia =
  MediaSchema.statics.recomputeConsensusForMedia;

// Check if the model already exists before compiling
const CameratrapMedia =
  mongoose.models.CameratrapMedia ||
  mongoose.model("CameratrapMedia", MediaSchema);

export default CameratrapMedia;
